{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Identifying existing approaches used to evaluate the sustainability of evidence-based interventions in healthcare: an integrative review",
      "reason": "The title identifies the report as a review ('an integrative review'), but does not use the term 'systematic review.' The methods (text_8, text_3) describe a systematic search and PRISMA-compliant process, so the review type is identified but not explicitly as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Identifying existing approaches used to evaluate the sustainability of evidence-based interventions in healthcare",
      "reason": "The title clearly conveys the main objective: identifying approaches to evaluate sustainability of evidence-based interventions (the intervention/exposure) in healthcare (the population/context)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "an integrative review",
      "reason": "The title provides supplementary methodological information by specifying the review design/study design scope as an integrative review, which per the methods (text_8) includes diverse data sources and study designs."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The background describes the current state of knowledge (limited evidence on sustainability evaluation, 17-year translation lag, maturing implementation science) and identifies the uncertainty that it is unclear which approaches are most effective."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used... Our review offers methodological recommendations for sustainability evaluation research and highlights the importance in understanding mechanisms of sustainability to advance the field.",
      "reason": "The importance and need for the review are explained: the gap in guidance on selecting approaches to evaluate sustainability and the aim to advance the field."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The manuscript acknowledges similar recent syntheses (citing [6-10], e.g., Lennox et al.) and explains how the current review differs by focusing on evaluation approaches, timing, methods, measures, and outcomes."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of approaches used to evaluate sustainability of EBIs, not a review of intervention effects, so describing a mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines evaluation approaches rather than assessing a specific complex intervention's components and outcomes, so a logic model requirement does not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review objectives are explicitly stated in a dedicated Aim section, also echoed in the abstract."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "Integrative reviews can include diverse data sources and do not restrict the type of study design.",
      "reason": "This is an integrative review of approaches to evaluating sustainability, not a review of intervention effects, so PICO-style planned comparisons do not apply."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical approach for sustainability ... • Were within a healthcare setting • Evaluated the sustainability of an EBI",
      "reason": "Table 1 specifies study characteristics for eligibility: study design (primary research with explicit design/methods), setting (healthcare, with definition in footnote g), and requirement of an explicit theoretical approach and independent sustainability evaluation component."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "table_0",
      "quote": "• Were published in a peer-review journal ... Articles were excluded if they: • Were secondary research • Were gray literature",
      "reason": "Publication status is specified (peer-reviewed primary research; gray literature excluded), but dissemination year and language restrictions are not stated in the eligibility criteria; the English-language restriction appears only in the Limitations section (text_21), not as an eligibility criterion."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses sustainability outcomes, but nowhere distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence specifies groups used in each synthesis or links them to review comparisons; the review descriptively categorizes approaches (framework, model, tool, instrument, theory) in results but no grouping for syntheses is defined in the methods."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Notable restrictions (e.g., healthcare settings only, independent sustainability evaluation component required, peer-reviewed publications only) are stated but no rationales for these restrictions are provided in the retrieved evidence."
    }
  ],
  "confidence": 88
}

